window.JA_GLOSSARY=[{"term": "exploit", "ja": "エクスプロイト", "desc": "ソフトウェアの脆弱性を突いて、作者が想定していない動作をさせるプログラムや手順。", "aliases": ["exploits", "exploitation"], "url": "https://ja.wikipedia.org/wiki/エクスプロイト"}, {"term": "payload", "ja": "ペイロード", "desc": "攻撃で、相手に送り込む本体のデータ。たとえば、実行させたいコード。", "aliases": ["payloads"]}, {"term": "shellcode", "ja": "シェルコード", "desc": "攻撃で相手に実行させる、小さな機械語のコード。多くは、シェル（操作用の画面）を起動する。", "aliases": ["shellcodes"], "url": "https://ja.wikipedia.org/wiki/シェルコード"}, {"term": "ASLR", "ja": "ASLR", "desc": "プログラムやライブラリを置くメモリの場所を、起動のたびにランダムに変える防御。攻撃者が、アドレスを当てにくくなる。", "url": "https://ja.wikipedia.org/wiki/アドレス空間配置のランダム化"}, {"term": "setuid", "ja": "setuid", "desc": "実行した人ではなく、ファイルの持ち主の権限で動くようにする、Unix のしくみ。", "url": "https://ja.wikipedia.org/wiki/Setuid"}, {"term": "EOF", "ja": "EOF（入力の終わり）", "desc": "End Of File の略。これ以上、読めるデータがないこと。"}, {"term": "tty", "ja": "TTY（端末）", "desc": "キーボードで入力して、文字で結果を見る、端末のこと。", "aliases": ["TTY", "pty"]}, {"term": "ELF", "ja": "ELF", "desc": "Linux などで使う、実行ファイルの形式。", "url": "https://ja.wikipedia.org/wiki/Executable_and_Linkable_Format"}, {"term": "libc", "ja": "libc", "desc": "多くのプログラムが共通で使う、C 言語の標準ライブラリ。", "url": "https://ja.wikipedia.org/wiki/標準Cライブラリ"}, {"term": "endianness", "ja": "エンディアン", "desc": "複数バイトの数を、メモリにどの順で並べるか。小さい桁から並べるのが little、大きい桁からが big。", "aliases": ["endian"], "url": "https://ja.wikipedia.org/wiki/エンディアン"}, {"term": "fuzzing", "ja": "ファジング", "desc": "でたらめに近いデータを大量に与えて、プログラムが壊れる場所を探す手法。", "aliases": ["fuzzer"], "url": "https://ja.wikipedia.org/wiki/ファジング"}, {"term": "CVE", "ja": "CVE", "desc": "脆弱性につけられる、世界共通の番号（例: CVE-2024-0001）。", "url": "https://ja.wikipedia.org/wiki/Common_Vulnerabilities_and_Exposures"}, {"term": "tube", "ja": "tube", "desc": "pwntools で、ソケット・プロセス・SSH などを、同じ操作で扱うための入れ物。名前なので、訳しません。"}, {"term": "context", "ja": "context", "desc": "pwntools の、全体の設定（アーキテクチャ、エンディアン、ログの量など）をまとめたオブジェクト。名前なので、訳しません。"}, {"term": "cyclic", "ja": "循環パターン（cyclic）", "desc": "どの 4 文字も 1 回しか現れない文字列。クラッシュしたときの値から、入力のどの位置かが分かる。"}];
